const rowsOf = (node) => { try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; } };
const activeClients = () => rowsOf('Read Clients').filter((c) => c.client_id && String(c.status || '').toLowerCase() === 'active');
const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const daysAgo = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 864e5); };

const within = (d, n) => { const a = daysAgo(d); return a !== null && a <= n; };
const leads = rowsOf('Read Leads'); const props = rowsOf('Read Proposals'); const clients = activeClients();
const health = rowsOf('Read Health'); const ledger = rowsOf('Read AI Ledger');
const l7 = leads.filter((l) => within(l.created_at, 7));
const hotWarm30 = leads.filter((l) => within(l.created_at, 30) && ['hot', 'warm'].includes(l.tier));
const src = {}; for (const l of l7) src[l.source || 'unknown'] = (src[l.source || 'unknown'] || 0) + 1;
const mrr = clients.reduce((s, c) => s + (Number(c.retainer_usd) || 0), 0);
const lastWeek = health.map((h) => h.week_of).sort().pop();
const hNow = health.filter((h) => h.week_of === lastWeek);
const atRisk = hNow.filter((h) => h.status === 'at-risk');
const retainer = Object.fromEntries(clients.map((c) => [c.client_id, Number(c.retainer_usd) || 0]));
const ai7 = ledger.filter((r) => within(r.timestamp, 7));
const aiSpend = ai7.reduce((s, r) => s + (Number(r.est_cost_usd) || 0), 0);
const aiBy = {}; for (const r of ai7) aiBy[r.caller] = Math.round(((aiBy[r.caller] || 0) + (Number(r.est_cost_usd) || 0)) * 100) / 100;
const kpis = {
  leads_7d: l7.length, hot_leads_7d: l7.filter((l) => l.tier === 'hot').length,
  avg_lead_score_7d: l7.length ? Math.round(l7.reduce((s, l) => s + (Number(l.score) || 0), 0) / l7.length) : null,
  lead_sources_7d: src, pipeline_value_30d_usd_mo: hotWarm30.reduce((s, l) => s + (Number(l.est_deal_value_usd) || 0), 0),
  proposals_7d: props.filter((p) => within(p.created_at, 7)).length,
  proposal_value_7d_usd_mo: props.filter((p) => within(p.created_at, 7)).reduce((s, p) => s + (Number(p.proposal_value_usd) || 0), 0),
  active_clients: clients.length, mrr_usd: mrr, new_clients_30d: clients.filter((c) => within(c.start_date, 30)).length,
  health: { healthy: hNow.filter((h) => h.status === 'healthy').length, watch: hNow.filter((h) => h.status === 'watch').length, at_risk: atRisk.length },
  at_risk_clients: atRisk.map((h) => ({ client: h.client_name, score: h.score, drivers: h.drivers })),
  mrr_at_risk_usd: atRisk.reduce((s, h) => s + (retainer[h.client_id] || 0), 0),
  ai_spend_7d_usd: Math.round(aiSpend * 100) / 100, ai_spend_by_workflow_7d: aiBy, ai_calls_7d: ai7.length,
  ai_cost_pct_of_weekly_mrr: mrr ? Math.round((aiSpend / (mrr * 12 / 52)) * 10000) / 100 : null,
};
const cfg = $('Config').first().json;
const schema = { type: 'object', additionalProperties: false, required: ['headline', 'scoreboard_commentary', 'council', 'top_priorities', 'risks', 'bold_bet'],
  properties: { headline: { type: 'string' }, scoreboard_commentary: { type: 'string' },
    council: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['advisor', 'take'], properties: { advisor: { type: 'string' }, take: { type: 'string' } } } },
    top_priorities: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['priority', 'why', 'owner_role'], properties: { priority: { type: 'string' }, why: { type: 'string' }, owner_role: { type: 'string' } } } },
    risks: { type: 'array', items: { type: 'string' } }, bold_bet: { type: 'string' } } };
return [{ json: { kpis, week_of: ymd(new Date()), brain: {
  skill: 'marketing-council', caller: 'CEO Brief', client: cfg.agency_name, effort: 'high', max_tokens: 8000, schema,
  context: { agency: cfg.agency_name, week_of: ymd(new Date()), kpis },
  task: `Convene the council to review ${cfg.agency_name}'s own business this week (we are the marketing agency; the KPIs are our pipeline, revenue, client health, and AI costs). Pick the 3-4 advisors whose lenses fit these numbers best, give each one sharp paragraph grounded in the data, then converge on exactly 3 priorities for this week, the main risks, and one bold bet.`,
} } }];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const li = (arr) => (arr || []).map((t) => `<li style="margin:0 0 6px">${esc(t)}</li>`).join('');
const card = (title, inner) => `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:18px 20px;margin:0 0 16px"><h3 style="margin:0 0 10px;font-size:16px;color:#111827">${esc(title)}</h3>${inner}</div>`;
const shell = (title, sub, inner) => `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;color:#1f2937;line-height:1.5"><div style="padding:24px 0 8px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6b7280">${esc(sub)}</div><h1 style="margin:4px 0 0;font-size:24px;color:#111827">${esc(title)}</h1></div>${inner}</div>`;
const pct = (v) => (v === null || v === undefined || Number.isNaN(v)) ? 'n/a' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`;

const x = $json; const k = x.kpis; const a = x.ai || {};
const cfg = $('Config').first().json;
const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString();
const tile = (label, v, sub) => `<td style="padding:12px;border:1px solid #e5e7eb;border-radius:8px;text-align:center;width:25%"><div style="font-size:12px;color:#6b7280">${label}</div><div style="font-size:22px;font-weight:700;color:#111827">${v}</div><div style="font-size:12px;color:#6b7280">${sub || ''}</div></td>`;
const council = (a.council || []).map((c) => `<li style="margin:0 0 10px"><b>${esc(c.advisor)}</b>: ${esc(c.take)}</li>`).join('');
const prios = (a.top_priorities || []).map((p) => `<li style="margin:0 0 8px"><b>${esc(p.priority)}</b> <span style="color:#6b7280">(${esc(p.owner_role)})</span><br>${esc(p.why)}</li>`).join('');
const html = shell(a.headline || 'Your week at a glance', `${cfg.agency_name} · CEO brief · week of ${x.week_of}`,
  `<table style="border-spacing:8px;margin:0 -8px 8px;width:100%"><tr>${tile('MRR', money(k.mrr_usd), `${k.active_clients} active clients`)}${tile('Leads (7d)', k.leads_7d, `${k.hot_leads_7d} hot · avg ${k.avg_lead_score_7d ?? '–'}`)}${tile('Pipeline (30d)', money(k.pipeline_value_30d_usd_mo), 'per month, hot + warm')}${tile('MRR at risk', money(k.mrr_at_risk_usd), `${k.health.at_risk} at-risk · ${k.health.watch} watch`)}</tr></table>`
  + `<table style="border-spacing:8px;margin:0 -8px 16px;width:100%"><tr>${tile('Proposals (7d)', k.proposals_7d, money(k.proposal_value_7d_usd_mo) + '/mo')}${tile('New clients (30d)', k.new_clients_30d)}${tile('AI spend (7d)', money(k.ai_spend_7d_usd), `${k.ai_calls_7d} calls`)}${tile('AI cost / MRR', k.ai_cost_pct_of_weekly_mrr === null ? '–' : k.ai_cost_pct_of_weekly_mrr + '%', 'of weekly MRR')}</tr></table>`
  + card('The scoreboard', `<p style="margin:0">${esc(a.scoreboard_commentary || x.ai_error || '')}</p>`)
  + card('Top 3 priorities this week', `<ol style="padding-left:18px;margin:0">${prios}</ol>`)
  + card('The council', `<ul style="padding-left:18px;margin:0">${council}</ul>`)
  + card('Risks', `<ul style="padding-left:18px;margin:0">${li(a.risks)}</ul>`)
  + card('One bold bet', `<p style="margin:0;font-weight:600">${esc(a.bold_bet)}</p>`)
  + (k.at_risk_clients.length ? card('Clients at risk', `<ul style="padding-left:18px;margin:0">${li(k.at_risk_clients.map((c) => `${c.client} (${c.score}): ${c.drivers}`))}</ul>`) : ''));
const slack_text = `:crystal_ball: *CEO brief: ${a.headline || ''}*\nMRR ${money(k.mrr_usd)} · leads ${k.leads_7d} (${k.hot_leads_7d} hot) · MRR at risk ${money(k.mrr_at_risk_usd)} · AI spend ${money(k.ai_spend_7d_usd)}\n*Priorities:*\n${(a.top_priorities || []).map((p, i) => `${i + 1}. ${p.priority}`).join('\n')}\n*Bold bet:* ${a.bold_bet || ''}`;
return [{ json: { subject: `CEO brief · ${x.week_of}: ${a.headline || ''}`.slice(0, 180), html, slack_text } }];
